import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Consider all complex roots z (counting multiplicity) of the equation z^{ {n} } + {a} z^{ {n_minus_one} } + {b} = 0, where {n} is an odd integer and {a},{b} are positive integers. How many of these roots are non-real and lie strictly inside the unit circle |z| < 1?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Generate an odd n >= 9
n = rng.randrange(9, 121, 2)  # 9,11,...,119
# Choose b in a modest range to keep numbers reasonable
b = rng.randint(1, 12)
# Ensure a > 1 + b, and make a not too small to strengthen the Rouché inequality
# Also keep a moderate upper bound for readability
a_low = b + 2
a_high = b + 40
if a_low > a_high:
    a_high = a_low + 5
a = rng.randint(a_low, a_high)
# Prepare return dict
return {
    'n': int(n),
    'a': int(a),
    'b': int(b),
    'n_minus_one': int(n - 1)
}

    def verifier(assign):
# Validate presence and types
required = ['n', 'a', 'b', 'n_minus_one']
for key in required:
    if key not in assign:
        # Missing key
        return (False, None)  # Missing assignment key
    if not isinstance(assign[key], int):
        return (False, None)  # Non-integer slot

n = assign['n']
a = assign['a']
b = assign['b']
nm1 = assign['n_minus_one']

# Domain constraints
if n < 9 or n % 2 == 0:
    return (False, None)  # n must be odd >= 9
if nm1 != n - 1:
    return (False, None)  # n_minus_one must match n-1
if a <= 0 or b <= 0:
    return (False, None)  # coefficients must be positive
if not (a > 1 + b):
    return (False, None)  # enforce Rouché dominance on |z|=1

# All constraints satisfied. By the analysis (Rouché on |z|=1), the number of zeros in |z|<1 equals n-1.
# We also ensure these zeros are non-real: for x in (-1,1), f(x) = x^{n-1}(x+a) + b > 0 (since n-1 is even and a>1+b>1), so no real roots in |x|<1.
answer = n - 1
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

